// A ordem da pessoa. Na bomba, ela vale por 30 min e passa por cima de todas.
const ordem = $input.first().json.output.ordem;

if (ordem === "DEVOLVER") {
  return [{ json: { dispositivo: "pessoa", devolver: true } }];
}

return [{
  json: {
    dispositivo: "pessoa",
    bomba: ordem === "LIGAR",
    motivo: "pedido no chat"
  }
}];
